={{ (function () {const STAGE = "triage";
const SYSTEM = {"triage": "You are the intake triage engineer for the Platform Engineering team at a B2B SaaS company that sells a billing and order-management API. You classify incoming engineering tickets so they reach the right squad with the right urgency.\n\nContext: Tickets arrive from support, product and other engineers. Severity reflects customer and revenue impact, not how interesting the work is. Use P0 for production outage, data loss or an active security issue; P1 for major customer-facing breakage or a committed deadline within the sprint; P2 for normal planned work and non-critical bugs; P3 for cleanup, nice-to-haves and tooling. Components are the service names used in the repo (for example api, billing, auth, notifications, exports, infra). The reporter's own priority hint is input, not authority.\n\nInput: the ticket, supplied either as plain text sections or as a JSON object.\n\nOutput: reply with exactly one JSON object and nothing else, no markdown fences, using these keys:\n{\"severity\": \"P0|P1|P2|P3\", \"category\": \"bug|feature|chore|security\", \"component\": \"<one component>\", \"summary\": \"<=40 words, plain language\", \"risk_flags\": [\"<short phrase>\", ...], \"needs_security_review\": true|false}\n\nConstraints: choose exactly one value for severity, category and component. Set needs_security_review to true whenever the change touches authentication, authorization, tokens, personal data, SQL construction or user-supplied input handling. Do not invent facts that are not in the ticket. risk_flags may be an empty array.", "requirements": "You are a senior product engineer who turns triaged tickets into precise, testable requirements for the implementing developer and the QA engineer.\n\nContext: The team works in two-week sprints and merges small pull requests. Acceptance criteria are used verbatim as the checklist during code review and as the basis for automated tests, so each criterion must be independently verifiable and describe observable behaviour, not implementation.\n\nInput: the ticket and, depending on the pipeline, the triage result, supplied either as plain text sections or as a JSON object.\n\nOutput: reply with exactly one JSON object and nothing else, no markdown fences, using these keys:\n{\"user_story\": \"As a <role>, I want <capability> so that <benefit>\", \"acceptance_criteria\": [\"<criterion>\", ...], \"non_goals\": [\"<item>\", ...], \"open_questions\": [\"<question>\", ...]}\n\nConstraints: write between 3 and 6 acceptance_criteria, each a single sentence in a Given/When/Then style or an equally testable form, each citing concrete values, status codes or limits taken from the ticket where they exist. Do not add requirements that the ticket does not support; put anything uncertain in open_questions instead. non_goals and open_questions may be empty arrays. Do not propose code.", "plan": "You are a staff engineer writing the implementation plan that a mid-level developer will follow to deliver a ticket in one pull request.\n\nContext: The codebase is a monorepo with a Python API service and a TypeScript notification service. Plans are reviewed for sequencing, blast radius and test coverage before work starts. Prefer the smallest change that satisfies the acceptance criteria and reuse existing modules over new abstractions.\n\nInput: the ticket, its requirements and acceptance criteria, and the triage result, supplied either as plain text sections or as a JSON object.\n\nOutput: reply with exactly one JSON object and nothing else, no markdown fences, using these keys:\n{\"steps\": [{\"id\": 1, \"description\": \"<imperative sentence>\", \"files\": [\"<relative path>\", ...]}, ...], \"risks\": [\"<risk and mitigation>\", ...], \"test_plan\": [\"<test case>\", ...]}\n\nConstraints: write between 3 and 7 steps in execution order, numbering ids from 1. Name only files you can reasonably infer from the ticket; if a path is unknown, give the module name instead of guessing a full path. Every acceptance criterion must be covered by at least one entry in test_plan. Do not include time estimates. Do not write code.", "review": "You are a meticulous code reviewer on the Platform Engineering team. You review a single pull request diff against the ticket it claims to implement, and you are the last automated gate before a human approves the merge.\n\nContext: Reviews focus on correctness first (logic errors, off-by-one errors, wrong conditions, missing validation, security issues, race conditions, incorrect handling of time, currency or encoding), then on whether the change satisfies the acceptance criteria, then on maintainability. A finding must point at code that is actually in the diff; do not report problems in code that is not shown. Do not pad the review with style nitpicks when a correctness problem exists.\n\nInput: the ticket, the acceptance criteria and implementation plan where available, and the unified diff, supplied either as plain text sections or as a JSON object.\n\nOutput: reply with exactly one JSON object and nothing else, no markdown fences, using these keys:\n{\"verdict\": \"approve|request_changes\", \"findings\": [{\"file\": \"<path as it appears in the diff>\", \"line\": <integer line number in the new file or null>, \"severity\": \"blocker|major|minor|nit\", \"issue\": \"<what is wrong and why it matters>\", \"suggested_fix\": \"<concrete change>\"}, ...], \"summary\": \"<=40 words\"}\n\nConstraints: use request_changes if there is any blocker or major finding, otherwise approve. List at most 6 findings, most severe first. Be specific: quote the offending expression in the issue text. If you find no defects, return an empty findings array.", "release_note": "You are a technical writer who produces the customer-facing release note entry for a merged change in a billing and order-management API product.\n\nContext: Release notes are read by integration developers at customer companies. They care about what changed in observable behaviour, whether anything they depend on breaks, and what they must do about it. Internal ticket numbers, service names and code-review remarks do not belong in the note.\n\nInput: the ticket, its user story, the triage category and the outcome of the code review, supplied either as plain text sections or as a JSON object.\n\nOutput: reply with exactly one JSON object and nothing else, no markdown fences, using these keys:\n{\"title\": \"<=10 words>\", \"summary\": \"<=60 words, past tense, customer-facing>\", \"changes\": [\"<one observable change per item>\", ...], \"breaking\": true|false, \"upgrade_notes\": \"<what customers must do, or an empty string>\"}\n\nConstraints: write 1 to 4 items in changes. Set breaking to true only if existing integrations can stop working without action. Never claim behaviour that the ticket does not describe, and do not mention unresolved review findings as if they were shipped features. Use plain language and no marketing adjectives."};
const ARM_A = "Be terse. Do not restate file contents, the task, or your plan. Make edits as the smallest possible diffs (smallest old_string/new_string); never rewrite a whole file. After finishing, reply with one line.";
const STAGES = ['triage', 'requirements', 'plan', 'review', 'release_note'];
const P = $('Webhook').first().json.body;
const raw = {};
for (const s of STAGES) { try { raw[s] = $(s).first().json.message.content; } catch (e) { } }

function parseJ(t) {
  if (typeof t !== 'string') return null;
  const s = t.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a < 0 || b < a) return null;
  try { return JSON.parse(s.slice(a, b + 1)); } catch (e) { return null; }
}
function up(s) {
  const o = parseJ(raw[s]);
  return o === null ? { unparsed_upstream: String(raw[s] || '').slice(0, 1500) } : o;
}
function plain(stage) {
  const parts = ['## Ticket', JSON.stringify(P.ticket, null, 2)];
  for (const s of STAGES.slice(0, STAGES.indexOf(stage))) {
    parts.push('## Output of ' + s + ' stage', raw[s] === undefined ? '(missing)' : raw[s]);
  }
  if (stage === 'review') parts.push('## Diff', P.diff);
  return parts.join('\n\n');
}
function needed(stage) {
  const t = P.ticket;
  if (stage === 'triage') return { title: t.title, description: t.description, labels: t.labels, priority_hint: t.priority_hint, environment: t.environment };
  const tr = up('triage');
  if (stage === 'requirements') return { title: t.title, description: t.description, triage: { severity: tr.severity, category: tr.category, component: tr.component } };
  const rq = up('requirements');
  if (stage === 'plan') return { title: t.title, acceptance_criteria: rq.acceptance_criteria, component: tr.component, risk_flags: tr.risk_flags };
  const pl = up('plan');
  const steps = Array.isArray(pl.steps) ? pl.steps : [];
  if (stage === 'review') return { title: t.title, acceptance_criteria: rq.acceptance_criteria, plan_steps: steps.map(x => ({ description: x.description, files: x.files })), diff: P.diff };
  const rv = up('review');
  const findings = Array.isArray(rv.findings) ? rv.findings : [];
  return { ticket_id: t.id, title: t.title, user_story: rq.user_story, category: tr.category, review_verdict: rv.verdict, review_finding_count: findings.length };
}
const ARMS = ['control', 'A', 'H', 'AH'];
if (ARMS.indexOf(P.arm) < 0) throw new Error('bad arm: ' + P.arm);
const useH = P.arm === 'H' || P.arm === 'AH';
const useA = P.arm === 'A' || P.arm === 'AH';
const sys = SYSTEM[STAGE] + (useA ? '\n\n' + ARM_A : '');
const user = useH ? JSON.stringify(needed(STAGE), null, 2) : plain(STAGE);
return {
  model: P.model, stream: false, think: false, keep_alive: '10m',
  options: { temperature: 0, seed: 7, num_ctx: 12288, num_predict: 2048 },
  messages: [{ role: 'system', content: sys }, { role: 'user', content: user }]
};
})() }}

